import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { COLORS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const COUNT = 72;

// Deterministic pseudo-random so the field is identical on every frame and render.
const rnd = (seed: number): number => {
  const x = Math.sin(seed * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
};

const ParticleDrift: React.FC<PrimitiveProps> = ({ fps }) => {
  const frame = useCurrentFrame();
  const t = frame / Math.max(1, fps); // seconds — unbounded; every motion below is periodic or wrapped

  // Read tokens inside the component: applyTheme() mutates them per render.
  const hues = [COLORS.tealBright, COLORS.teal, COLORS.gold, COLORS.leather];

  // Two very slow nebula glows, driven by sin/cos so they never settle.
  const glowA = {
    x: Math.sin(t * 0.055) * 8,
    y: Math.cos(t * 0.041) * 6,
  };
  const glowB = {
    x: Math.cos(t * 0.037) * 9,
    y: Math.sin(t * 0.049) * 7,
  };

  return (
    <AbsoluteFill
      style={{
        background: `linear-gradient(165deg, ${COLORS.papyrus} 0%, ${COLORS.ink} 55%, ${COLORS.vellum} 100%)`,
        overflow: "hidden",
      }}
    >
      <AbsoluteFill
        style={{
          background: `radial-gradient(60% 40% at 78% 12%, ${COLORS.leather}, transparent 65%)`,
          opacity: 0.22,
          filter: "blur(60px)",
          transform: `translate(${glowA.x}%, ${glowA.y}%)`,
        }}
      />
      <AbsoluteFill
        style={{
          background: `radial-gradient(55% 38% at 22% 88%, ${COLORS.teal}, transparent 62%)`,
          opacity: 0.14,
          filter: "blur(70px)",
          transform: `translate(${glowB.x}%, ${glowB.y}%)`,
        }}
      />

      {new Array(COUNT).fill(0).map((_, i) => {
        const x0 = rnd(i + 1) * 104 - 2;
        const y0 = rnd(i + 2.3);
        const size = 3 + rnd(i + 5.1) * 11;
        const speed = 0.05 + rnd(i + 7.7) * 0.055; // screen-heights per second
        const swayAmp = 1.2 + rnd(i + 11.3) * 4;
        const swayHz = 0.04 + rnd(i + 13.9) * 0.06;
        const phase = rnd(i + 17.5) * Math.PI * 2;
        const hue = hues[Math.floor(rnd(i + 19.1) * hues.length) % hues.length];

        // Wrapped vertical travel: p stays in [0,1) forever; the sine envelope
        // fades each particle to zero at both ends, so the wrap is invisible.
        const p = (y0 + t * speed) % 1;
        const fade = Math.sin(Math.PI * p);
        const twinkle = 0.75 + 0.25 * Math.sin(t * (0.5 + rnd(i + 29.3) * 0.7) * Math.PI * 2 + phase);
        const opacity = (0.14 + rnd(i + 23.7) * 0.3) * fade * twinkle;
        const x = x0 + Math.sin(t * swayHz * Math.PI * 2 + phase) * swayAmp;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: `${x}%`,
              top: `${(1 - p) * 100}%`,
              width: size,
              height: size,
              marginLeft: -size / 2,
              marginTop: -size / 2,
              borderRadius: "50%",
              background: hue,
              boxShadow: `0 0 ${size * 3}px ${hue}`,
              opacity,
            }}
          />
        );
      })}

      <AbsoluteFill
        style={{
          background: `radial-gradient(78% 58% at 50% 50%, transparent 40%, ${COLORS.papyrus} 100%)`,
          opacity: 0.6,
        }}
      />
    </AbsoluteFill>
  );
};

export default ParticleDrift;
